import{_ as r,a as t,b as i,c as l,d as o}from"./chunks/7b481882d0158c964c66.Ck8ucOyy.js";import{_ as s,C as n,o as h,c as d,j as e,a as c,E as u,a5 as m}from"./chunks/framework.DNkHA0lr.js";const T=JSON.parse('{"title":"你本该感到不知所措（如何快速学习任何技能）","description":"","frontmatter":{"title":"你本该感到不知所措（如何快速学习任何技能）","originalTitle":"You’re Supposed To Feel Overwhelmed (How To Learn Any Skill FAST)","date":"2024-02-02","originalUrl":"https://thedankoe.com/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking/","minutes":10,"sourceHash":"96eae7eed1c9208a59250341ae6b54c37a6be70750936b1bcf04e208d6bc7374","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking/"}]]},"headers":[],"relativePath":"letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking.md","filePath":"letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking.md"}'),f={name:"letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking.md"};function b(g,p,_,k,x,v){const a=n("ArticleMeta");return h(),d("div",null,[p[0]||(p[0]=e("h1",{id:"你本该感到不知所措-如何快速学习任何技能",tabindex:"-1"},[c("你本该感到不知所措（如何快速学习任何技能） "),e("a",{class:"header-anchor",href:"#你本该感到不知所措-如何快速学习任何技能","aria-label":'Permalink to "你本该感到不知所措（如何快速学习任何技能）"'},"​")],-1)),u(a),p[1]||(p[1]=m('<p><a href="https://www.youtube.com/embed/KrCzMfvSDv0?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><p><img src="'+r+'" alt=""></p><p>人们总以为自己不应该感到不知所措。</p><ul><li>你感到轻微的不适</li><li>你的大脑讨厌这种感觉</li><li>你还没有训练过自己的觉察力</li><li>你瞬间缩回到舒适和快乐中</li><li>你切断了通向拓展、成长和理解的道路</li></ul><p>当我尝试学习新东西时，一切都毫无头绪。</p><p>我感到不知所措，感觉自己不仅没有进步，反而还在倒退。</p><p>实际上，我是在为大脑识别模式做准备。当我让自己暴露在新材料中时，我的潜意识正像海绵一样吸收信息。</p><p>慢慢地，然后突然之间，一切都豁然开朗了。</p><p>那个“咔哒”一声接通的瞬间。</p><p>那个“啊哈！原来如此”的时刻。</p><p>那场名为“洞察”的雪崩狠狠砸进你的心灵。</p><p>但前提是，你必须忍受这种不适，深入感受它，并让你那堪比超级计算机的大脑把一切拼凑起来。</p><p>起初什么都没发生，然后一切水到渠成。</p><p>如果你想了解将所学转化为有意义的职业的完整哲学和步骤，去亚马逊买一本《专注的艺术》（<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art of Focus</a>）。</p><h2 id="现实代谢——精神肥胖的根源" tabindex="-1">现实代谢——精神肥胖的根源 <a class="header-anchor" href="#现实代谢——精神肥胖的根源" aria-label="Permalink to &quot;现实代谢——精神肥胖的根源&quot;">​</a></h2><p>你感到不知所措，是因为你消化现实的速度不够快。</p><p>你无法应对这种不知所措，因为它消耗了你的注意力。</p><p>你唯一能关注的，就是那些充斥大脑的负面想法：这行不通、你会失败、你本可以把时间花在更好的事情上。</p><p>在健身（bodybuilding）中，你通过增加进食量、用抗阻训练给身体施加压力，以及获得充足的休息来恢复，从而练出肌肉。</p><p>在这个过程中你会长一点脂肪，但如果你想看到显著的效果，这是不可避免的。</p><p>在健脑（mindbuilding）中，你通过增加信息摄入量、用具有挑战性的概念给大脑施加压力，以及适当休息让潜意识去咀嚼复杂问题，从而积累知识。</p><p>当你学习新东西时，它就是崭新的。</p><p>你的大脑还没有建立起让它运作自如的系统。</p><p>你并不是生来就知道如何走路、说话、吃饭、开车、发短信、整理床铺、扔橄榄球，以及你在工作、休息和娱乐中所做的任何其他事情。</p><p>你训练了你的心理代谢能力，从而能够轻松消化那部分现实。你已经练出了精神肌肉，足以举起做这些事带来的情绪劳动。</p><p>过去和现在的区别在于，你已经把某些限制接纳为你身份的一部分。</p><p>你那老化的大脑，如果不通过正念加以约束，一有不适的苗头就会退缩。</p><p>而当你听从并服从那个并不想为你着想的大脑时，那就会变成你的默认状态。你变成了一个自我编程为逃避一切痛苦的机器人，哪怕这种痛苦正是为你的人生带来意义、成就感和目标的东西。</p><h3 id="活在你能力的边缘" tabindex="-1">活在你能力的边缘 <a class="header-anchor" href="#活在你能力的边缘" aria-label="Permalink to &quot;活在你能力的边缘&quot;">​</a></h3><p>如果你消费太多而创造太少，你的大脑就会变胖。</p><p>如果你创造太多而消费太少，你的大脑就会变瘦。</p><p>这两种结果我们都不想要。</p><p>当通过平衡消费与创造，使你生活中的信息流最大化时，你就会遇到有意义的事件。</p><p>你会<em>感受</em>到对未来深深的兴奋，对现在的充实，以及对过去的感激。</p><p>这些感受应该被视为一个机会，用来记录你可以与他人分享的生命中的重要部分。</p><p>当你读了一本好书，偶然发现一个让你兴奋的道理时，把它写下来。</p><p>当你因为正在取得的进步而对当下感到充实时，把它写下来。</p><p>当你感激你的过去引导你来到这一刻（哪怕你犯过错）时，把它写下来（写在像 <a href="https://kortex.co/" target="_blank" rel="noreferrer">Kortex</a> 这样的工具里）。</p><p>随着你记录这些信号的笔记越来越多，你就拥有了可以用来复制这些体验的数据。</p><p>你可以训练你的大脑，将占据这些意识状态作为一种基准线。</p><p>你的生活质量会提升到一个高度稳定的水平。</p><h2 id="宇宙性思维——你大多数问题的解药" tabindex="-1">宇宙性思维——你大多数问题的解药 <a class="header-anchor" href="#宇宙性思维——你大多数问题的解药" aria-label="Permalink to &quot;宇宙性思维——你大多数问题的解药&quot;">​</a></h2><p>你感觉很糟，是因为未来的你正注视着你的一举一动，而他们不喜欢眼前看到的一切。</p><p>你大多数问题的解药是：</p><p>拉远视角。采用你理想自我的视角。打破让你深陷负面思想混乱循环的狭隘焦点。</p><p>认清你所处的位置，选择你想去的地方，用教育和执行力来填补差距。</p><p>大多数人都生活在一种封闭的心智状态中。</p><p>他们沦为焦虑、不知所措和压力的受害者，这让他们无法透过问题看到更广阔的画面（从而去解决问题）。</p><p>人们总是盯着一句糟糕的歌词，而不是欣赏一首好歌。</p><p>人们总是盯着一个难看的像素点，而不是欣赏一幅美丽的图像。</p><p>你忽略了局势的背景并做出了错误解读，所以你一直停滞不前，无法学习。</p><p>你必须训练自己拉远视角的能力，采用更高的视角，并把各种情况看作是对你最终目标有利的。</p><p>养成这个习惯：</p><p>当你感到不知所措时，停下来，打破应激反应的循环。</p><p>通过敞开心扉，在视角的阶梯上向上攀登：</p><p><strong>1) 你当前的视角</strong>——盘点你当下的处境。</p><p><strong>2) 你理想自我的视角</strong>——最高版本的你会怎么做？</p><p><strong>3) 宇宙的视角</strong>——超越所有限制，从最高视角来看，我们的大多数担忧都是非理性且毫无意义的。</p><p>这3个阶段由我书《专注的艺术》（<a href="https://theartoffocusbook.com/" target="_blank" rel="noreferrer">The Art of Focus</a>）封面上的FOCI符号所代表。</p><p><img src="'+t+'" alt=""></p><p>只有当你把视角拉得足够远时，你才能发现那些潜力、联系、方向和创意，从而让你学到超出你现有认知的东西。</p><p>宇宙性思维是一种心智状态，在其中你可以洞察模式，并从宏观大局来理解各种事物。</p><p>你可以注意到健身、健脑和建立企业之间的巨大相似性——比如渐进式超负荷、张力作用时间以及适当的营养——从而提升这三者的成果。</p><p>在宇宙层面，你可以注意到肌肉、想法和产品的生与死——这能帮助你平静地顺应你的身体、心智和企业的流动——或者做出带来指数级增长的决策。</p><h2 id="如何让学习速度提升10倍" tabindex="-1">如何让学习速度提升10倍 <a class="header-anchor" href="#如何让学习速度提升10倍" aria-label="Permalink to &quot;如何让学习速度提升10倍&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>当你学会如何学习时，你能在6个月内取得别人5年的成果。</p><p>让我们把上面学到的所有东西落实到实际步骤中。</p><h3 id="_1-创造一个清晰度催化剂" tabindex="-1">1) 创造一个清晰度催化剂 <a class="header-anchor" href="#_1-创造一个清晰度催化剂" aria-label="Permalink to &quot;1) 创造一个清晰度催化剂&quot;">​</a></h3><p>在我的人生中，有几个时刻我在学习、理解和进步上实现了巨大飞跃：</p><ul><li>写我的书</li><li>打造我的产品</li><li>写这些时事通讯</li></ul><p>它们都有什么共同点？</p><p>我把它们当成一个项目来对待。</p><p>一个项目具备：</p><ul><li>一个大纲，这样你就可以记录日常生活中的想法来填补这个大纲。</li><li>里程碑，让你对下一步有方向和清晰的认知。</li><li>一个现实世界的截止日期，逼迫你采取行动，否则你的生存就会受挫。</li><li>实验、试错，让你能把失败转化为教训。</li></ul><p>这为心流状态提供了一个完美的环境。</p><p>这里有激发新鲜感和多巴胺的模式识别，有来自里程碑的清晰度，有来自截止日期的挑战，还有来自现实的反馈。</p><p>决定你想学什么。</p><p>创造一个你要发布给别人看的真实项目。</p><p>如果你不知道该创建什么项目，看看别人做过什么。</p><p>如果你想学 Photoshop，你的项目可以是任何东西，从一张图形到一幅数字艺术场景。</p><p>如果你想学习如何健身，你的项目就是你的身体、营养方案和训练计划。</p><p>你的项目大纲不需要完美。它可以从一份杂乱无章的想法清单开始，记录你认为自己必须做和必须学的东西。</p><p>项目是一个经验的锚点。</p><p>现在你有地方可以写下要去尝试的想法、知识和技术了。</p><p>当我写书的时候，我的书籍大纲让生活变得有意义。我遇到的几乎每一个想法都可以添加到大纲中。</p><p>我感觉自己又像个孩子了。我变得痴迷其中。</p><p>每一件事都可以透过一个新镜头来看待。我项目的镜头。</p><h3 id="_2-边构建边学习" tabindex="-1">2) 边构建边学习 <a class="header-anchor" href="#_2-边构建边学习" aria-label="Permalink to &quot;2) 边构建边学习&quot;">​</a></h3><p>如果你没在构建，你就没在学习。</p><p>如果你没有把学到的东西积极应用到盘踞在脑海中的问题上，你只是在堆砌无用的知识，它们很快就会变成被遗忘的脑雾。</p><p>当你<em>开始</em>构建某样东西时，你只需要知道少数几件事：基础知识。</p><p>你还没到去研究高级策略的时候。</p><p>基础知识会带你走完 80% 的路程（对大多数人来说，这意味着数百万美元的收入、健硕的体格，或毫无压力的生活）。</p><p>新的策略会带你走完接下来的 20%，但这部分心智带宽应该留给你对少数特定技能和兴趣的痴迷、精通以及你的毕生事业。</p><p>当你有一个要构建的项目时，做以下一项或两项：</p><ul><li>购买一个关于该主题的入门级课程</li><li>在 YouTube 上观看教授基础知识的概述视频</li></ul><p>学习它们，直到你清楚下一步该做什么。然后放手去做，当你遇到问题时：</p><ul><li>回头参考课程或视频的相关章节</li><li>直接搜索如何解决这个问题</li><li>观看别人<em>构建</em>与你类似项目的教程，看看他们是如何克服这些问题的</li></ul><p>学习是解决问题，而不是尽可能多地囤积知识。</p><h3 id="_3-教你所学" tabindex="-1">3) 教你所学 <a class="header-anchor" href="#_3-教你所学" aria-label="Permalink to &quot;3) 教你所学&quot;">​</a></h3><p><img src="'+l+'" alt=""></p><p>当然，我推荐通过写作作为<a href="/letters/the-one-person-business-revisited-turn-yourself-into-a-business">个人品牌</a>（或者你的公开简历）来公开教学，这样你就可以在学习的同时吸引高薪机会。（这也是我在《两小时作家》（<a href="https://2hourwriter.com/" target="_blank" rel="noreferrer">2 Hour Writer</a>）中所教的内容）。</p><ul><li>公开写作，让人们批评你。</li><li>教你的朋友，以此引出有趣的对话。</li><li>就该主题做笔记，但写作的语气要像是在教你自己。</li></ul><p>教学几乎是强迫你去理清信息的脉络。</p><p>你必须构建它的结构、解释它，并确保你没有传递错误的知识。</p><p>当我写这些时事通讯时，我并不懂所有的事情。但我可以保证，4年的写作大大加速了我对所热爱主题的学习，远超我陷在教程地狱里所能学到的。</p><p>当你建立一个品牌（不是商业意义上的，而是指你向世界展示的外在形象）时，构建和教学就融进了你的工作中。</p><p>你的生活变成了一系列有意义的过程：解决问题、学习如何解决问题、教导他人，并在做这些事的同时获得收入。我相信这就是进化所赋予的：多亏了互联网，人们能够毫无障碍地做自己热爱的事情。</p><p>关于冒名顶替综合征：</p><p>很简单——保持诚实。</p><p>不要捏造你的经验。不要对你所掌握的知识撒谎。用你学习它时的视角去教导别人。</p><p>像<em>“我在23小时内读完了《专注的艺术》（The Art of Focus），以下是我在加入新贵阶层时学到的改变人生的教训”</em>这样简单又吸引眼球的内容，真实地反映了你当前在学习旅程中所处的阶段。</p><p>就像营销产品一样，只要别去承诺你还没有得到的结果就行了。</p><h3 id="_4-拓展进入新层次的心智" tabindex="-1">4) 拓展进入新层次的心智 <a class="header-anchor" href="#_4-拓展进入新层次的心智" aria-label="Permalink to &quot;4) 拓展进入新层次的心智&quot;">​</a></h3><p><img src="'+o+'" alt=""></p><p>到这个时候，你可能仍然会感到不知所措，或者觉得自己没学到多少东西。</p><p>这是一件好事。</p><p>你的大脑已经为模式识别做好了准备。</p><p>所以：</p><ul><li><strong>将自己投入未知</strong> —— 让你自己沉浸在与你试图学习的领域相关的文化、环境和信息中。</li><li><strong>通过重复和接触来调节你的心智</strong> —— 慢慢去理解那些在该领域取得成功的人所用的行话、词汇和技能组合。</li><li><strong>让你的心智在不适中扩展</strong> —— 你能做的最糟糕的事情，就是在感受到成长的阵痛时选择放弃。</li></ul><p>你没有看到结果，因为你还不是那个能看到结果的人。</p><p>这个过程通过让旧版本的你死去，让你蜕变成一个全新的人。</p><p>就像你养成新习惯时，你必须离开那个滋生你坏习惯的旧环境。</p><p>为了让这更具实操性：</p><ul><li><strong>读书</strong> —— 书本让你仅用6小时的阅读，就能获得别人10年的心血。</li><li><strong>看讲座</strong> —— 长文章和视频让你在20分钟内获得别人3天的努力。</li><li><strong>关注新的人</strong> —— 这与其说是为了消费短内容，不如说是为了训练你的大脑，让你融入那个群体。</li></ul><p>买3本书。</p><p>一本畅销书，一本技术类书籍，一本历史类书籍。</p><p>快速啃完它们，不要让你的痴迷冷却。</p><p>这看起来可能是一个漫长的过程，但我们并不是试图停留在表面学习某样东西，我们是在试图以最快的速度成为大师。</p><h3 id="_5-建立联系以巩固理解" tabindex="-1">5) 建立联系以巩固理解 <a class="header-anchor" href="#_5-建立联系以巩固理解" aria-label="Permalink to &quot;5) 建立联系以巩固理解&quot;">​</a></h3><p>当你精通一件事时，精通其他事情就会变得更容易。</p><p>原则是普适的。它们相互重叠。</p><p>当你精通了健身，你就能用一半的时间精通商业，然后再用一半的时间精通人际关系。</p><p>大多数人从未精通过他们生命中的任何一个领域，因此他们从未体验过指数级的个人成长。</p><p>当你觉得自己对正在尝试学习的主题有了扎实的理解时：</p><ul><li><strong>拉高一层视角</strong> —— 从“Photoshop”转向“平面设计”再到“创意工作”。</li><li><strong>记录信号</strong> —— 当你的大脑发出重要信息的信号时，把它写下来。</li><li><strong>构建更好的项目</strong> —— 从全新的心智层次出发，构建一个能带你走向你渴望的成功的新项目。</li></ul><p>在我自己的经验中，当我揭开一层层表象，从网页设计拓展到营销，再到内容创作，最后到形而上学时，我的知识产生了复利效应。</p><p>这也是开启你一人企业的绝佳方式。</p><p>先从在一个领域里学习、教学和构建开始，然后随着受众的扩大再向外拓展。</p><p>在 <a href="https://university.kortex.co/" target="_blank" rel="noreferrer">Kortex University</a> 里，我们可以帮助你做到这一点，并在90天内开启你的数字职业生涯。</p><p>现在，去学习，去构建，享受你的周末吧。</p><p>Dan</p><hr><p><a href="/en/letters/i-discovered-a-way-to-learn-10x-faster-reality-metabolism-universal-thinking">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',145))])}const P=s(f,[["render",b]]);export{T as __pageData,P as default};
